package vn.edu.hunre.nhom11.carrental.booking.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import vn.edu.hunre.nhom11.carrental.catalog.domain.Car; import vn.edu.hunre.nhom11.carrental.identity.domain.User;
@Entity @Table(name="bookings") public class Booking { @Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)private User customer;@ManyToOne(optional=false)private Car car;@Column(nullable=false)private LocalDate pickupDate;@Column(nullable=false)private LocalDate returnDate;private String pickupLocation;private String returnLocation;@Column(length=500)private String notes;@Column(nullable=false,precision=12,scale=2)private BigDecimal totalAmount;@Column(nullable=false,precision=12,scale=2)private BigDecimal paidAmount=BigDecimal.ZERO;@Enumerated(EnumType.STRING)private BookingStatus status=BookingStatus.PENDING;private Instant createdAt=Instant.now();
 public Long getId(){return id;}public User getCustomer(){return customer;}public void setCustomer(User v){customer=v;}public Car getCar(){return car;}public void setCar(Car v){car=v;}public LocalDate getPickupDate(){return pickupDate;}public void setPickupDate(LocalDate v){pickupDate=v;}public LocalDate getReturnDate(){return returnDate;}public void setReturnDate(LocalDate v){returnDate=v;}public String getPickupLocation(){return pickupLocation;}public void setPickupLocation(String v){pickupLocation=v;}public String getReturnLocation(){return returnLocation;}public void setReturnLocation(String v){returnLocation=v;}public String getNotes(){return notes;}public void setNotes(String v){notes=v;}public BigDecimal getTotalAmount(){return totalAmount;}public void setTotalAmount(BigDecimal v){totalAmount=v;}public BigDecimal getPaidAmount(){return paidAmount;}public void setPaidAmount(BigDecimal v){paidAmount=v;}public BookingStatus getStatus(){return status;}public void setStatus(BookingStatus v){status=v;}public Instant getCreatedAt(){return createdAt;}
}

